*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:        #f7f8fa;
  --color-surface:   #ffffff;
  --color-border:    #e2e6ed;
  --color-primary:   #4f46e5;
  --color-primary-h: #3730a3;
  --color-text:      #1a1d23;
  --color-muted:     #5e6673;
  --color-answer-bg: #f9fafb;
  --radius:          12px;
  --shadow:          0 1px 4px rgba(0,0,0,.08), 0 4px 16px rgba(0,0,0,.06);
  --transition:      200ms ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Page header ── */
.page-header {
  background: linear-gradient(135deg, var(--color-primary) 0%, #7c3aed 100%);
  color: #fff;
  text-align: center;
  padding: 4rem 1.5rem 3rem;
}
.page-header__eyebrow {
  display: inline-block;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  background: rgba(255,255,255,.18);
  padding: .25rem .75rem;
  border-radius: 999px;
  margin-bottom: 1.25rem;
}
.page-header h1 {
  font-size: clamp(1.75rem, 5vw, 3rem);
  font-weight: 800;
  letter-spacing: -.02em;
  margin-bottom: .75rem;
}
.page-header__sub {
  font-size: 1.125rem;
  opacity: .88;
  max-width: 36rem;
  margin: 0 auto;
}

/* ── Main content ── */
main {
  max-width: 760px;
  margin: 0 auto;
  padding: 3rem 1.5rem 5rem;
}

/* ── Category heading ── */
.category-heading {
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin: 2.5rem 0 1rem;
}
.category-heading:first-of-type { margin-top: 0; }

/* ── FAQ list ── */
.faq-list {
  display: flex;
  flex-direction: column;
  gap: .625rem;
  list-style: none;
}

/* ── Individual disclosure item ── */
.example {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}
.example:has([aria-expanded="true"]) {
  border-color: #c7d2fe;
  box-shadow: 0 2px 8px rgba(79,70,229,.12), 0 6px 20px rgba(79,70,229,.08);
}

/* ── Trigger ── */
.example__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.125rem 1.375rem;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  transition: background var(--transition);
  border-radius: var(--radius); /* for focus ring containment */
}
.example__trigger:hover { background: #f3f4f6; }
.example__trigger:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: -3px;
  border-radius: var(--radius);
}

/* Icon */
.example__icon {
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  color: var(--color-primary);
  transition: transform var(--transition);
  aria-hidden: true; /* structural, not for CSS — set in HTML */
}
[aria-expanded="true"] .example__icon {
  transform: rotate(45deg);
}

/* ── Panel ── */
.details {
  padding: 0 1.375rem 1.25rem;
  border-top: 1px solid var(--color-border);
  background: var(--color-answer-bg);
}
.details p {
  font-size: .9375rem;
  color: var(--color-muted);
  padding-top: 1rem;
  max-width: 65ch;
}
.details p + p { margin-top: .625rem; }
.details a {
  color: var(--color-primary);
  text-decoration: underline;
  text-underline-offset: 3px;
}
.details a:hover { color: var(--color-primary-h); }

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .example { border: 1px solid ButtonText; }
  .example__trigger:focus-visible { outline: 3px solid Highlight; }
  .example__icon { forced-color-adjust: auto; }
}

/* ── Reflow (320 px) ── */
@media (max-width: 400px) {
  .page-header { padding: 2.5rem 1rem 2rem; }
  main { padding: 2rem 1rem 3rem; }
  .example__trigger { padding: 1rem 1rem; font-size: .9375rem; }
  .details { padding: 0 1rem 1rem; }
}
