(function () {
  'use strict';

  function init() {
    document.querySelectorAll('.example__trigger').forEach(function (btn) {
      const panel = btn.closest('.example').querySelector('.details');
      if (!panel) return;

      // Collapse on init — content stays visible without JS (reader mode / no-JS).
      btn.setAttribute('aria-expanded', 'false');
      panel.hidden = true;

      btn.addEventListener('click', function () {
        toggle(btn, panel);
      });

      // Escape closes the open panel and returns focus to trigger.
      panel.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') {
          collapse(btn, panel);
          btn.focus();
        }
      });
    });
  }

  function toggle(btn, panel) {
    const isOpen = btn.getAttribute('aria-expanded') === 'true';
    isOpen ? collapse(btn, panel) : expand(btn, panel);
  }

  function expand(btn, panel) {
    btn.setAttribute('aria-expanded', 'true');
    panel.hidden = false;
  }

  function collapse(btn, panel) {
    btn.setAttribute('aria-expanded', 'false');
    panel.hidden = true;
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
