+.details a {
+  color: var(--color-primary);
+  text-decoration: underline;
+  text-underline-offset: 3px;
+}
+.details a:hover { color: var(--color-primary-h); }
+
+/* ── Reduced motion ── */
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after { transition: none !important; }
+}
+
+/* ── Forced colors ── */
+@media (forced-colors: active) {
+  .example { border: 1px solid ButtonText; }
+  .example__trigger:focus-visible { outline: 3px solid Highlight; }
+  .example__icon { forced-color-adjust: auto; }
+}
+
+/* ── Reflow (320 px) ── */
+@media (max-width: 400px) {
+  .page-header { padding: 2.5rem 1rem 2rem; }
+  main { padding: 2rem 1rem 3rem; }
+  .example__trigger { padding: 1rem 1rem; font-size: .9375rem; }
+  .details { padding: 0 1rem 1rem; }
+}
+
')

